import { FileBlob, SpreadsheetFile } from '@oai/artifact-tool';

const filePath = 'D:/4A/亚马逊供应商和开店总表-2026 (1).xlsx';
const workbook = await SpreadsheetFile.importXlsx(await FileBlob.load(filePath));
const sheet = workbook.worksheets.getItem('Sheet1');
const values = sheet.getRange('A2:M220').values;

const asNumber = (value) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const parsed = Number(value.replace(/[$,]/g, '').trim());
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
};

const rows = values.filter((row) => String(row[0] ?? '').trim() !== '');
let both = 0;
let discounted = 0;
let equal = 0;
let invalidHigher = 0;
let listOnly = 0;
let saleOnly = 0;
let neither = 0;
let discountSum = 0;
const anomalies = [];

for (const row of rows) {
  const sku = String(row[0] ?? '').trim();
  const listPrice = asNumber(row[11]);
  const salePrice = asNumber(row[12]);
  if (listPrice !== null && salePrice !== null) {
    both += 1;
    if (listPrice > salePrice) {
      discounted += 1;
      discountSum += (listPrice - salePrice) / listPrice;
    } else if (listPrice === salePrice) {
      equal += 1;
    } else {
      invalidHigher += 1;
      anomalies.push({ sku, listPrice, salePrice });
    }
  } else if (listPrice !== null) {
    listOnly += 1;
  } else if (salePrice !== null) {
    saleOnly += 1;
  } else {
    neither += 1;
  }
}

console.log(JSON.stringify({
  dataRows: rows.length,
  bothPricesPresent: both,
  listHigherThanSale: discounted,
  equalPrices: equal,
  saleHigherThanList: invalidHigher,
  listOnly,
  saleOnly,
  neither,
  averageDiscountPct: discounted ? Number((discountSum / discounted * 100).toFixed(2)) : null,
  anomalies: anomalies.slice(0, 20),
}, null, 2));

