import fs from 'node:fs/promises';
import { FileBlob, SpreadsheetFile } from '@oai/artifact-tool';

const templatePath = 'E:/Desktop/PriceAndQuantity.xlsm';
const masterPath = 'C:/Users/24243/Documents/Codex/2026-08-11/7-30-slack-plugin-slack-openai/4A_Amazon_Operations/source_workbooks/亚马逊供应商和开店总表-2026 (1).xlsx';
const outputDir = 'outputs/019ff179-ce00-7621-9ae6-13daf0989ce8';
const outputPath = `${outputDir}/4A_PriceAndQuantity_100_SKUs_2026-08-17.xlsx`;
const saleStart = '2026-08-18';
const saleEnd = '2026-08-31';

const toNumber = (value) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const parsed = Number(value.replace(/[$,]/g, '').trim());
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
};

const master = await SpreadsheetFile.importXlsx(await FileBlob.load(masterPath));
const masterRows = master.worksheets.getItem('Sheet1').getRange('A2:M220').values;

const eligible = [];
const excluded = { reversed: [], equal: [], missingSale: [], missingBoth: [] };
for (const row of masterRows) {
  const sku = String(row[0] ?? '').trim();
  if (!sku) continue;
  const listPrice = toNumber(row[11]);
  const salePrice = toNumber(row[12]);
  if (listPrice !== null && salePrice !== null && listPrice > salePrice) {
    eligible.push({ sku, listPrice, salePrice });
  } else if (listPrice !== null && salePrice !== null && listPrice < salePrice) {
    excluded.reversed.push({ sku, listPrice, salePrice });
  } else if (listPrice !== null && salePrice !== null) {
    excluded.equal.push({ sku, listPrice, salePrice });
  } else if (listPrice !== null) {
    excluded.missingSale.push({ sku, listPrice });
  } else {
    excluded.missingBoth.push({ sku });
  }
}

if (eligible.length !== 100) throw new Error(`Expected 100 eligible SKUs, found ${eligible.length}`);
const skuSet = new Set(eligible.map((row) => row.sku));
if (skuSet.size !== eligible.length) throw new Error('Duplicate eligible SKUs detected');

const workbook = await SpreadsheetFile.importXlsx(await FileBlob.load(templatePath));
const template = workbook.worksheets.getItem('Template');
const firstRow = 7;
const lastRow = firstRow + eligible.length - 1;

template.getRange(`A${firstRow}:A${lastRow}`).values = eligible.map((row) => [row.sku]);
template.getRange(`G${firstRow}:G${lastRow}`).values = eligible.map((row) => [row.listPrice]);
template.getRange(`K${firstRow}:M${lastRow}`).values = eligible.map((row) => [row.salePrice, saleStart, saleEnd]);

await fs.mkdir(outputDir, { recursive: true });
const output = await SpreadsheetFile.exportXlsx(workbook);
await output.save(outputPath);

const preview = await workbook.render({
  sheetName: 'Template',
  range: 'A1:M18',
  scale: 1.2,
  format: 'png',
});
await fs.writeFile('.sheet_analysis/price_upload_after.png', new Uint8Array(await preview.arrayBuffer()));

const populated = template.getRange(`A${firstRow}:M${lastRow}`).values;
const errors = await workbook.inspect({
  kind: 'match',
  sheetId: 'Template',
  range: `A1:AF${lastRow}`,
  searchTerm: '#REF!|#DIV/0!|#VALUE!|#NAME\\?|#N/A',
  options: { useRegex: true, maxResults: 100 },
  maxChars: 5000,
});

console.log(JSON.stringify({
  outputPath,
  rowsWritten: populated.length,
  firstSku: eligible[0],
  lastSku: eligible.at(-1),
  saleStart,
  saleEnd,
  excludedCounts: Object.fromEntries(Object.entries(excluded).map(([key, rows]) => [key, rows.length])),
  reversed: excluded.reversed,
  formulaErrorScan: errors.ndjson,
}, null, 2));

