{"kind":"table","sheet":"Data Definitions","address":"A1:F28","rows":28,"cols":6,"values":[["How to complete your inventory template",null,null,null,null,null],["Group Name","Field Name","Local Label Name","Accepted Values","Example","Required?"],["Listing Identity",null,null,null,null,null],[null,"contribution_sku#1.value","SKU","This attribute indicates the SKU number as assigned by the contributor","ABC123","Required"],["Offer (US) - (Sell on Amazon), (US) - (Amazon Business (B2B))",null,null,null,null,null],[null,"fulfillment_availability#1.fulfillment_channel_code","Fulfillment Channel Code (US)","For those merchants using Amazon fulfillment services, this designates which fulfillment network will be used. Specifying a value other than DEFAULT will cancel the Merchant-fulfilled offering.","AMAZON_NA","Required"],[null,"fulfillment_availability#1.quantity","Quantity (US)","Enter the quantity of the item you are making available for sale. This is your current inventory commitment (as a whole number)","152","Conditionally Required"],[null,"fulfillment_availability#1.lead_time_to_ship_max_days","Handling Time (US)","Provide the time, in days, between when you receive an order for an item and when you can ship the item","5","Optional"],[null,"fulfillment_availability#1.restock_date","Restock Date (US)","Provide the date that product will be restocked using YYYY-MM-DD format","2020-05-05","Optional"],[null,"fulfillment_availability#1.is_inventory_available","Inventory Always Available (US)","Always available inventory is an alternative to quantity that allows inventory to never deplete. Enabling or disabling will toggle this feature on or off. Note that a quantity cannot be specified when provided.","Enabled","Conditionally Required"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.our_price#1.schedule#1.value_with_tax","Your Price USD (Sell on Amazon, US)","Provide base price of the item at which it is being offered to the intended buyer segment (Sell on Amazon)","9.00","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.automated_pricing_merchandising_rule_plan#1.merchandising_rule.rule_id","Pricing Rule (Sell on Amazon, US)","The pricing rule that will automate price on this offer (Sell on Amazon)","Competitive Price Rule by Amazon","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.minimum_seller_allowed_price#1.schedule#1.value_with_tax","Minimum Seller Allowed Price (Sell on Amazon, US)","Provide the minimum seller allowed price (Sell on Amazon)","259.99","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.maximum_seller_allowed_price#1.schedule#1.value_with_tax","Maximum Seller Allowed Price (Sell on Amazon, US)","Provide the maximum seller allowed price (Sell on Amazon)","259.99","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.discounted_price#1.schedule#1.value_with_tax","Sale Price USD (Sell on Amazon, US)","The price at which you offer the product for sale. (Sell on Amazon)","219.99","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.discounted_price#1.schedule#1.start_at","Sale Start Date (Sell on Amazon, US)","The date that the sale price will begin to override the product's standard price(YYYY-MM-DD format); the sale price will be displayed after 0:00AM of Sale From Date. (Sell on Amazon)","2017-06-30","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.discounted_price#1.schedule#1.end_at","Sale End Date (Sell on Amazon, US)","The last date that the sale price will override the item's standard price (YYYY-MM-DD format); the product's standard price will be displayed after 0:00AM of Sale End Date. (Sell on Amazon)","2017-07-01","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.start_at.value","Offering Release Date (Sell on Amazon, US)","Provide your price start date using YYYY-MM-DD format (Sell on Amazon)","2017-06-30","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=ALL]#1.end_at.value","Stop Selling Date (Sell on Amazon, US)","Provide your price end date using YYYY-MM-DD format (Sell on Amazon)","2017-07-01","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.our_price#1.schedule#1.value_with_tax","Your Price USD (Amazon Business (B2B), US)","Provide base price of the item at which it is being offered to the intended buyer segment (Amazon Business (B2B))","9.00","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.minimum_seller_allowed_price#1.schedule#1.value_with_tax","Minimum Seller Allowed Price (Amazon Business (B2B), US)","Provide the minimum seller allowed price (Amazon Business (B2B))","259.99","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.maximum_seller_allowed_price#1.schedule#1.value_with_tax","Maximum Seller Allowed Price (Amazon Business (B2B), US)","Provide the maximum seller allowed price (Amazon Business (B2B))","259.99","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.start_at.value","Offering Release Date (Amazon Business (B2B), US)","Provide your price start date using YYYY-MM-DD format (Amazon Business (B2B))","2017-06-30","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.end_at.value","Stop Selling Date (Amazon Business (B2B), US)","Provide your price end date using YYYY-MM-DD format (Amazon Business (B2B))","2017-07-01","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.quantity_discount_plan#1.schedule#1.discount_type","Quantity Price Type (Amazon Business (B2B), US)","Provide whether the quantity price type is fixed, a price set in local currency for each quantity threshold, or a percentage of business price (Amazon Business (B2B))","Fixed, Percent","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.quantity_discount_plan#1.schedule#1.levels#1.lower_bound","Quantity Threshold (Lower Bound, Amazon Business (B2B), US)","Provide the minimum purchase quantity necessary to receive the discount. It will apply to all units if the quantity threshold is met. (Amazon Business (B2B))","5, 10","Optional"],[null,"purchasable_offer[marketplace_id=ATVPDKIKX0DER][audience=B2B]#1.quantity_discount_plan#1.schedule#1.levels#1.value","Quantity Price (Fixed Price/Percentage Discount, Amazon Business (B2B), US)","Provide the quantity price for each quantity threshold or the discount percentage offered on the business price for each quantity threshold. (Amazon Business (B2B))","10, 20","Optional"],[null,"merchant_shipping_group[marketplace_id=ATVPDKIKX0DER]#1.value","Shipping Template (US)","Shipping Templates define your shipping regions and fees. Amazon assigns a default template, which you can modify or configure additional templates in your Shipping Settings.","Heavy Bulky Products, NCR Large Appliance Delivery","Conditionally Required"]]}
