import fs from 'node:fs/promises';
import { FileBlob, SpreadsheetFile } from '@oai/artifact-tool';

const reportPath = 'E:/Desktop/所有商品报告_08-17-2026.txt';
const masterPath = 'C:/Users/24243/Documents/Codex/2026-08-11/7-30-slack-plugin-slack-openai/4A_Amazon_Operations/source_workbooks/亚马逊供应商和开店总表-2026 (1).xlsx';

const normalizeSku = (value) => String(value ?? '').trim().replace(/\s+/g, ' ').toUpperCase();
const toNumber = (value) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const parsed = Number(value.replace(/[$,]/g, '').trim());
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
};

const raw = (await fs.readFile(reportPath, 'utf8')).replace(/^\uFEFF/, '');
const lines = raw.split(/\r?\n/).filter((line) => line.length > 0);
const headers = lines[0].split('\t');
const reportRows = lines.slice(1).map((line) => {
  const values = line.split('\t');
  return Object.fromEntries(headers.map((header, index) => [header, values[index] ?? '']));
});

const reportBySku = new Map();
for (const row of reportRows) {
  const key = normalizeSku(row['seller-sku']);
  if (!reportBySku.has(key)) reportBySku.set(key, []);
  reportBySku.get(key).push(row);
}

const master = await SpreadsheetFile.importXlsx(await FileBlob.load(masterPath));
const masterRows = master.worksheets.getItem('Sheet1').getRange('A2:M220').values
  .filter((row) => String(row[0] ?? '').trim() !== '')
  .map((row) => ({
    sku: String(row[0]).trim(),
    key: normalizeSku(row[0]),
    listPrice: toNumber(row[11]),
    salePrice: toNumber(row[12]),
  }));

const validDiscount = masterRows.filter((row) => row.listPrice !== null && row.salePrice !== null && row.listPrice > row.salePrice);
const masterDuplicates = [...Map.groupBy(masterRows, (row) => row.key)].filter(([, rows]) => rows.length > 1);
const reportDuplicates = [...reportBySku].filter(([, rows]) => rows.length > 1);

const matched = [];
const missingInReport = [];
for (const masterRow of validDiscount) {
  const liveRows = reportBySku.get(masterRow.key);
  if (!liveRows) {
    missingInReport.push(masterRow);
    continue;
  }
  for (const live of liveRows) {
    const currentPrice = toNumber(live.price);
    matched.push({
      ...masterRow,
      currentPrice,
      status: live.status,
      fulfillment: live['fulfillment-channel'],
      asin: live.asin1,
      quantity: toNumber(live.quantity),
      liveSku: live['seller-sku'],
      wouldRaiseDuringSale: currentPrice !== null && masterRow.salePrice > currentPrice,
      wouldLowerDuringSale: currentPrice !== null && masterRow.salePrice < currentPrice,
      saleSameAsCurrent: currentPrice !== null && masterRow.salePrice === currentPrice,
    });
  }
}

const activeMatched = matched.filter((row) => String(row.status).toLowerCase() === 'active');
const safeActive = activeMatched.filter((row) => !row.wouldRaiseDuringSale);
const counts = (rows, key) => Object.fromEntries([...Map.groupBy(rows, (row) => row[key] || '(blank)')].map(([value, list]) => [value, list.length]));

console.log(JSON.stringify({
  report: {
    lines: lines.length,
    rows: reportRows.length,
    uniqueSkus: reportBySku.size,
    duplicateSkuGroups: reportDuplicates.length,
    statuses: counts(reportRows, 'status'),
    fulfillment: counts(reportRows, 'fulfillment-channel'),
  },
  master: {
    rows: masterRows.length,
    validDiscountRows: validDiscount.length,
    duplicateSkuGroups: masterDuplicates.length,
  },
  reconciliation: {
    validDiscountMatchedRows: matched.length,
    validDiscountMissingInReport: missingInReport.length,
    activeMatched: activeMatched.length,
    inactiveMatched: matched.length - activeMatched.length,
    safeActiveRows: safeActive.length,
    activeWouldLower: activeMatched.filter((row) => row.wouldLowerDuringSale).length,
    activeSamePrice: activeMatched.filter((row) => row.saleSameAsCurrent).length,
    activeWouldRaise: activeMatched.filter((row) => row.wouldRaiseDuringSale).length,
    activeFulfillment: counts(activeMatched, 'fulfillment'),
    missingSkus: missingInReport.map((row) => row.sku),
    inactiveSamples: matched.filter((row) => String(row.status).toLowerCase() !== 'active').slice(0, 20),
    wouldRaiseSamples: activeMatched.filter((row) => row.wouldRaiseDuringSale).slice(0, 20),
    safeSamples: safeActive.slice(0, 10),
  },
}, null, 2));

