    else buckets.reversed.push(row);
  } else if (listPrice !== null) buckets.listOnly.push(row);
  else if (salePrice !== null) buckets.saleOnly.push(row);
  else buckets.missingBoth.push(row);
}

const discounts = buckets.validDiscount.map((row) => (row.listPrice - row.salePrice) / row.listPrice).sort((a, b) => a - b);
const avg = discounts.reduce((a, b) => a + b, 0) / (discounts.length || 1);
const median = discounts.length ? discounts[Math.floor(discounts.length / 2)] : null;
const suspiciousDiscounts = buckets.validDiscount
  .map((row) => ({ ...row, discountPct: (row.listPrice - row.salePrice) / row.listPrice }))
  .filter((row) => row.discountPct >= 0.5 || row.salePrice <= 0)
  .map(({ sku, rowNumber, listPrice, salePrice, discountPct }) => ({ sku, rowNumber, listPrice, salePrice, discountPct: Number((discountPct * 100).toFixed(1)) }));

const oldMap = new Map(prior.rows.map((row) => [row.key, row]));
const newMap = new Map(rows.map((row) => [row.key, row]));
const changes = [];
for (const row of rows) {
  const old = oldMap.get(row.key);
  if (!old) continue;
  if (old.listPrice !== row.listPrice || old.salePrice !== row.salePrice) {
    changes.push({
      sku: row.sku,
      oldList: old.listPrice,
      newList: row.listPrice,
      oldSale: old.salePrice,
      newSale: row.salePrice,
    });
  }
}

const newSkus = rows.filter((row) => !oldMap.has(row.key)).map((row) => row.sku);
const removedSkus = prior.rows.filter((row) => !newMap.has(row.key)).map((row) => row.sku);

const formulaErrors = await current.workbook.inspect({
  kind: 'match',
  searchTerm: '#REF!|#DIV/0!|#VALUE!|#NAME\\?|#N/A',
  options: { useRegex: true, maxResults: 300 },
  maxChars: 6000,
});

const previews = [
  ['Sheet1', 'A1:N25', 'website_master_sheet1_top.png'],
  ['Sheet1', 'A196:N220', 'website_master_sheet1_bottom.png'],
  ['变体', 'A1:C40', 'website_master_variants_top.png'],
  ['变体', 'A41:C80', 'website_master_variants_bottom.png'],
  ['Sheet3', 'A1:N21', 'website_master_sheet3_left.png'],
  ['Sheet3', 'O1:AG21', 'website_master_sheet3_right.png'],
];
for (const [sheetName, range, fileName] of previews) {
  const preview = await current.workbook.render({ sheetName, range, scale: 1, format: 'png' });
  await fs.writeFile(`.sheet_analysis/${fileName}`, new Uint8Array(await preview.arrayBuffer()));
}

console.log(JSON.stringify({
  current: {
    rows: rows.length,
    uniqueSkus: bySku.size,
    duplicateGroups: duplicates,
    priceBuckets: Object.fromEntries(Object.entries(buckets).map(([key, value]) => [key, value.length])),
    discountStats: {
      averagePct: Number((avg * 100).toFixed(1)),
      medianPct: median === null ? null : Number((median * 100).toFixed(1)),
      minPct: discounts.length ? Number((discounts[0] * 100).toFixed(1)) : null,
      maxPct: discounts.length ? Number((discounts.at(-1) * 100).toFixed(1)) : null,
    },
    reversed: buckets.reversed.map(({ sku, rowNumber, listPrice, salePrice }) => ({ sku, rowNumber, listPrice, salePrice })),
    listOnly: buckets.listOnly.map(({ sku, rowNumber, listPrice }) => ({ sku, rowNumber, listPrice })),
    saleOnly: buckets.saleOnly.map(({ sku, rowNumber, salePrice }) => ({ sku, rowNumber, salePrice })),
    missingBoth: buckets.missingBoth.map(({ sku, rowNumber }) => ({ sku, rowNumber })),
    suspiciousDiscounts,
  },
  comparisonToPrior: {
    priorRows: prior.rows.length,
    changedPriceRows: changes.length,
    changes,
    newSkus,
    removedSkus,
  },
  formulaErrorScan: formulaErrors.ndjson,
}, null, 2));

