function writeDataSheet(sheet, headersRow, rows, tableName, widths, options = {}) {
  sheet.showGridLines = false;
  const cols = headersRow.length;
  const totalRows = rows.length + 1;
  const range = sheet.getRangeByIndexes(0, 0, totalRows, cols);
  range.values = [headersRow, ...rows];
  const header = sheet.getRangeByIndexes(0, 0, 1, cols);
  header.format = { fill: navy, font: { bold: true, color: "#FFFFFF" }, rowHeight: 26, verticalAlignment: "center" };
  const table = sheet.tables.add(`A1:${columnLetter(cols)}${totalRows}`, true, tableName);
  table.style = "TableStyleMedium2";
  sheet.freezePanes.freezeRows(1);
  widths.forEach((w, i) => { sheet.getRangeByIndexes(0, i, totalRows, 1).format.columnWidth = w; });
  if (options.currencyCols) for (const c of options.currencyCols) sheet.getRangeByIndexes(1, c, rows.length, 1).format.numberFormat = '"$"#,##0.00';
  if (options.wrapCols) for (const c of options.wrapCols) sheet.getRangeByIndexes(1, c, rows.length, 1).format.wrapText = true;
  if (rows.length) sheet.getRangeByIndexes(1, 0, rows.length, cols).format.verticalAlignment = "top";
}

function columnLetter(n) {
  let s = "";
  while (n > 0) { n--; s = String.fromCharCode(65 + (n % 26)) + s; n = Math.floor(n / 26); }
  return s;
}

